/**
 * One canonical TanStack Start specification for every new ZoeBuild project.
 * Websites, apps and stores are generated by Zoé from user intent, rather
 * than selecting a different runtime at project creation.
 */
export function createStarterProjectSpecification(name: string): Record<string, unknown> {
  const normalizedName = name.trim();
  if (!normalizedName) throw new Error("Project name is required.");
  return {
    version: 1,
    name: normalizedName,
    projectType: "fullstack-app",
    targets: ["web"],
    requirements: {
      backend: true,
      database: false,
      auth: false,
      storage: false,
      payments: false,
      email: false,
      commerce: false,
    },
    pages: ["Home"],
    stackId: "tanstack-start-v1",
    deployment: { preference: "managed-runtime" },
  };
}
